  return (
    <section data-testid="invoice-detail-page">
      <h1>Invoice</h1>
      <LineItemList invoiceId={id} />
      <LineItemForm invoiceId={id} />
      <InvoiceDetail.Slot invoiceId={id} />
    </section>
  );
}

